// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipAttentionItem) predicate.RelationshipAttentionItem {
	return predicate.RelationshipAttentionItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationshipAttentionItem) predicate.RelationshipAttentionItem {
	return predicate.RelationshipAttentionItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationshipAttentionItem) predicate.RelationshipAttentionItem {
	return predicate.RelationshipAttentionItem(sql.NotPredicates(p))
}
